            if '=' not in text: continue
            key=text.split('=',1)[0].strip()
            ident=(section,key)
            if ident in seen:
                dup=(seen[ident],n); break
            seen[ident]=n
        if dup:
            first,n=dup
            sys.stderr.write(f'  ┌─ {path or "-"}:{n}:1\n  │\n')
            sys.stderr.write(f'{first} │ {lines[first-1]}\n  │ - duplicate found here\n')
            sys.stderr.write(f'{n} │ {lines[n-1]}\n  │ ^ duplicate key\n\n')
