                return
    if 'invalid escape' in message:
        for n,line in enumerate(lines,1):
            bad=re.search(r'\\[^btnfr"\\uU]',line)
            if bad:
                col=bad.start()+1
                sys.stderr.write(f'  ┌─ {path or "-"}:{n}:{col}\n  │\n{n} │ {line}\n  │ {" "*(col-1)}^ invalid escape sequence\n\n')
                return
    if lines and 'invalid value:' in message:
        match=re.search(r'(?<![\w.])0[0-9]+(?![\w.])', message)
        line=lines[-1]
        if match and '=' in line:
            token=match.group(0); start=line.find('=')+1
            while start<len(line) and line[start].isspace(): start+=1
            if line[start:start+len(token)]==token:
                col=start+1
                sys.stderr.write(f'  ┌─ {path or "-"}:{len(lines)}:{col}\n  │\n')
                sys.stderr.write(f'{len(lines)} │ {line}\n  │ {" "*(col-1)}{"^"*len(token)} zero-padded integers are not allowed\n\n')
                return
    # A missing right-hand side points immediately after the equals sign.
    if message == 'expected value' and lines:
        n=len(lines); line=lines[-1]
        if line.rstrip().endswith('='):
            col=len(line.rstrip())+1
            if source.endswith('\n'):
