                sys.stderr.write(f'  ┌─ {path or "-"}:{n}:{col}\n  │  \n')
                sys.stderr.write(f'{n} │   {line}\n  │ ╭'+('─'*width)+'^\n')
                sys.stderr.write(f'{n+1} │ │ \n  │ ╰^ expected value\n\n')
