        if target:
            n,line=target; col=1; span=max(1,line.find('=')+1); message='expected key'
    if target:
        n,line=target
        sys.stderr.write(f'  ┌─ {path or "-"}:{n}:{col}\n  │\n{n} │ {line}\n  │ {" "*(col-1)}{"^"*span} {message}\n\n')
        if extra:
            n,line,col,span,message=extra
            sys.stderr.write(f'error: invalid TOML\n  ┌─ {path or "-"}:{n}:{col}\n  │\n{n} │ {line}\n  │ {" "*(col-1)}{"^"*span} {message}\n\n')

def run(args):
    files=[]; i=0; stdin=False; no_auto=False
    while i<len(args):
        a=args[i]
        if a in ('-h','--help'):
            import helpdata; helpdata.show('lint'); return 0
        if a in ('--no-schema','--default-schema-catalogs','--no-auto-config','--verbose','--log-spans'):
            no_auto |= a=='--no-auto-config'; i+=1; continue
        if a in ('-c','--config','--schema','--schema-catalog','--colors','--cache-path'):
            i+=2; continue
        if a.startswith('--schema=') or a.startswith('--colors=') or a.startswith('--config='):
            i+=1; continue
        if a.startswith('-') and a!='-':
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: taplo lint [OPTIONS] [FILES]...\n\nFor more information, try '--help'.\n")
            return 2
        if a=='-': stdin=True
        else:
            matches=glob.glob(a,recursive=True); files.extend(matches or [a])
        i+=1
    if stdin:
        source=sys.stdin.read()
        try: tomlparse.parse(source)
        except Exception as e:
            _error(e, '-', source) ; return 1
        return 0
    if not files:
        files=glob.glob('**/*.toml',recursive=True)
    files=list(dict.fromkeys(os.path.abspath(p) for p in files if os.path.exists(p)))
    if files:
        sys.stderr.write(' INFO taplo:lint_files:collect_files: found files total=%d excluded=0 files=%s cwd=%s\n' %
                         (len(files), json.dumps(files), json.dumps(os.getcwd())))
    failed=False
    for path in files:
        # File collection ignores unmatched explicit paths/globs in Taplo.
        if not os.path.exists(path) or os.path.isdir(path):
            continue
        source=''
        try:
            with open(path,encoding='utf-8') as f: source=f.read()
            tomlparse.parse(source)
        except Exception as e:
            failed=True
            _error(e, path, source)
    return 1 if failed else 0

